fn is_palindrome(text: Vec<char>) -> bool {
    let mut left = 0;
    let mut right = text.len().wrapping_sub(1); // Handle empty case
    
    while left < right {
        let left_char = text[left];
        let right_char = text[right];
        
        // Convert to lowercase if uppercase ASCII
        let left_lower = if ('A'..='Z').contains(&left_char) {
            // Convert to lowercase by adding 32 (ASCII difference)
            (left_char as u8 + 32) as char
        } else {
            left_char
        };
        
        let right_lower = if ('A'..='Z').contains(&right_char) {
            (right_char as u8 + 32) as char
        } else {
            right_char
        };
        
        if left_lower != right_lower {
            return false;
        }
        
        left += 1;
        right -= 1;
    }
    
    true
}